import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/19-How-to-make-a-parallel-computing-scrambled-egg-dish.html","title":"19-4分钟炒蛋的秘密：并行计算初体验","lang":"zh-CN","frontmatter":{"title":"19-4分钟炒蛋的秘密：并行计算初体验","icon":"read","date":"2025-04-20T22:02:07.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":18,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"426204f3d36310dd2ccdfefb5c28f8f6a73d7fb6","time":1745221442000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新标题"},{"hash":"95fe8be9e9691873327cbe0569288f78db3b9ca8","time":1745217456000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"9cf73a7eeb1a0bd13afd0c495e2df229803a3d50","time":1745201733000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"a0ad4a4daeb6c9cf59700858149a2fae378bf52c","time":1745199192000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"炒鸡蛋"},{"hash":"7e37fe559f0c4d91fffc918711f893deeb3626c1","time":1745157972000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"c0696c0b1f0651fc9c5cf9836451581449e27f1e","time":1745157938000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"773771c51d4b9f5188f373ad148eee08d3d2aa09","time":1745157753000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":6.85,"words":2056},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/19-How-to-make-a-parallel-computing-scrambled-egg-dish.md"}`),a={name:`19-How-to-make-a-parallel-computing-scrambled-egg-dish.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你有没有试过自己下厨？哪怕是最简单的一道炒鸡蛋，一开始也可能让你手忙脚乱：鸡蛋没打匀、葱花飞出碗、锅太热差点糊锅……最后一道菜做下来，时间过去了五六分钟，感觉自己像经历了一场战斗。</p><p>你可能会说：“我就是不熟练嘛！”当然，熟练度很重要。但今天我想告诉你：做饭慢，可能还有一个原因——<strong>你没用上“并行计算”的脑子</strong>。（并行计算思维）</p><p>听起来有点酷对吧？先别急着追问，我们先换个角度，从天马行空的“寻找外星人”说起。</p><h2 id="_1-当无线电遇见火星信号" tabindex="-1"><a class="header-anchor" href="#_1-当无线电遇见火星信号"><span>1. 当无线电遇见火星信号</span></a></h2><p>100多年前，无线电刚被发明不久，科学界就开始畅想：如果我们能把电波送出去，那会不会也能接收到外星文明发来的信号？</p><figure><img src="/assets/sss-DRnb87_7.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>传奇科学家尼古拉·特斯拉当年在搞实验时，还真以为自己听到了火星发来的问候。第二年，无线电发明人古列尔莫·马可尼也声称，他的设备接收到了来自宇宙的“电报”。虽然后来的研究表明，这些信号很可能只是误判，但科学家们从此便踏上了<strong>搜寻外星人</strong>的道路。</p><p>不过，无线电波属于电磁波家族，较可见光波长更长，能穿越尘埃与大气层，所以科学家们并未气馁。</p><figure><img src="/assets/raw-20250421123631503-C5f8QuXE.png" alt="阿雷西博望远镜" tabindex="0" loading="lazy"><figcaption>阿雷西博望远镜</figcaption></figure><p>科学家们建起了巨大的射电望远镜，比如那座外形像铁锅的“阿雷西博望远镜”，直径有350米那么大——差不多能放下一百层楼。只要有外星信号飘进来，它都能接住！</p><figure><img src="/assets/raw-20250421125652716-Cj4iVdby.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>然而，问题很快来了：<strong>信号太多，处理不过来</strong>。</p><p>你可以想象一下，就像你一秒钟就收到了几千封信，哪怕是24小时不睡觉，也根本看不过来。于是科学家们想到用<strong>超级计算机</strong>来帮忙。但——超级计算机价格昂贵，政府又不愿意出这笔钱，毕竟“找外星人”听上去不像是当务之急。</p><p>那怎么办？科学家们总得想个办法。</p><p>如果是你，你会怎么办呢？号召全国热爱外星人的同胞团结起来，给政府施加压力？还是干脆号召大家捐钱给科学家，帮助他们租一台超级计算机？</p><p>这些方法都不错，但是跟下面的这个方法一比，可就差远了。</p><h2 id="_2-一场家用电脑的大联欢" tabindex="-1"><a class="header-anchor" href="#_2-一场家用电脑的大联欢"><span>2. 一场家用电脑的大联欢</span></a></h2><p>有个叫<strong>戴维·格迪</strong>的计算机科学家，在一次聚会上灵光一闪：<strong>既然大家都有电脑，为什么不让全世界的家用电脑来一起找外星人呢？</strong></p><p>你想想，在20世纪90年代的时候，互联网已经在世界上比较普及了。有许多人家都买了家用计算机。这时候，只要制作一个分析外星人信号数据的软件，把这个软件装在你家的计算机里。然后，再把望远镜接收到的信号通过网络传到你的计算机上。等你睡觉了计算机闲着没事的时候，就可以分析这些信号了。</p><figure><img src="/assets/image-20250421105008540-BCMBlNBe.png" alt="SETI@home" tabindex="0" loading="lazy"><figcaption>SETI@home</figcaption></figure><p>于是，他和一群朋友开发了一个叫做“<strong>在家寻找外星人</strong>（SETI@home）”的程序——只要你愿意，就可以把它装到你家的电脑上。白天你用电脑干自己的事，晚上睡觉了，电脑闲着，它就会自动开始分析外星信号。</p><p>从1999年开始，这个项目一度火遍全球，有520万人参与。到2013年，它的总运算能力已经能和世界上最强的超级计算机媲美。</p><p>为什么这么厉害？</p><p>戴维把一个大任务拆分成很多可以同时进行的小任务，让很多计算机同时运算，最后就顺利解决了问题。这种方法，在计算机科学领域，算是<strong>并行计算</strong>的一种。所谓并行，就是同时进行的意思。</p><p>省字版：<strong>并行计算</strong>——把大任务拆成许多小任务，然后<strong>同时分给很多人（或者很多电脑）去做</strong>，效率自然就高了。</p><p>那你肯定要问了，找外星人和做饭有什么关系呀？别着急，我们回头看看，如何用并行计算<strong>提升做饭的速度</strong>。</p><h2 id="_3-炒鸡蛋-其实也能并行" tabindex="-1"><a class="header-anchor" href="#_3-炒鸡蛋-其实也能并行"><span>3. 炒鸡蛋，其实也能并行</span></a></h2><p>听起来很高大上？其实炒鸡蛋也能用这个思路！</p><p>我们来算一算普通炒鸡蛋的步骤：</p><ol><li><strong>准备食材</strong>：打鸡蛋（10s）、切葱（20s）、搅拌葱花和鸡蛋（30s），总共大概1分钟；</li><li><strong>热锅</strong>：花1分钟把油烧热；<s>烧油需要1分钟；</s></li><li><strong>下锅翻炒</strong>：把蛋炒熟，大概3分钟。</li></ol><p>如果你按顺序一步步做，需要5分钟。</p><p>但如果换个思路呢？<strong>边准备食材边加热锅</strong>，时间就可以重叠。也就是说，你可以先把锅放上灶台开火，然后一边让锅热着，一边打蛋、切葱、搅拌。准备好之后，锅也差不多热了，直接炒！这样一来，总共只需要4分钟。</p><p>这就是<strong>并行炒蛋法</strong>！</p><p>而最开始那种按部就班、一项接一项完成的方式，就是<strong>串行计算</strong>——每一步都要等上一步做完，虽然简单，但效率不高。</p><p>举个具体例子：所谓串行的意思，就像是往糖葫芦上穿山楂果。只能按顺序一个一个地穿，前一个没穿好，后面的就得等着。串行计算看起来很省心，但通过前面的例子你肯定也知道了，它会浪费时间。</p><h2 id="_4-超级计算机的秘密" tabindex="-1"><a class="header-anchor" href="#_4-超级计算机的秘密"><span>4. 超级计算机的秘密</span></a></h2><figure><img src="/assets/raw-20250421142033954-CjGotHkP.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>现实中的超级计算机，现实生活中的超级计算机之所以威力巨大，也是因为它也采用了并行计算。</p><p>我们一般的电脑里有8个、12个计算核心，而超级计算机里就有<strong>几百万个</strong>。</p><p>超级计算机正是靠着<strong>几百万个核心一起工作</strong>，才能在极短时间内完成海量运算。一个复杂的大问题，拆成成千上万块的小问题，每一块分别送给不同的计算核心处理，运算速度自然飙升。</p><p><s>其实你身边也有不少机会使用并行思维，比如做作业的时候可以先读题再写答案，做饭时可以先洗菜再烧水，还有小组合作完成大项目时，每个人分工明确，各自完成自己的部分……这些，都是并行思维的好例子。</s></p><p>想想看，日常生活中还有哪些场景可以并行优化？是同时听音乐和做作业？还是一边听课一边预习？</p><h2 id="_5-如果你想参与" tabindex="-1"><a class="header-anchor" href="#_5-如果你想参与"><span>5. 如果你想参与……</span></a></h2><p>说到这儿，你可能兴奋地想加入寻找外星人的行列。可惜“SETI@home”项目已经暂停了，阿雷西博望远镜也因为年久失修而垮塌。但没关系！科学探索永不停歇，现在还有一个叫“Folding@home”的项目，正在邀请大家帮忙研究病毒蛋白质的结构，为人类攻克疾病出一份力。</p><h2 id="_6-小结" tabindex="-1"><a class="header-anchor" href="#_6-小结"><span>6. 小结</span></a></h2><p>一开始，你或许以为<strong>并行计算</strong>只是科学家才用得到的复杂概念。但其实，只要你愿意动动脑，它就在你炒鸡蛋、写作业、做项目的生活里无处不在。</p><p>用并行的眼光看世界，你会发现——时间和效率，真的可以被你掌控！</p>`,47)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};